import { createApp } from 'vue';
import App from './App.vue';
import './global.css';
import { parseStatusSource } from './parser';

function mountStatusBars() {
  const mounts = Array.from(document.querySelectorAll<HTMLElement>('.ty-status-app:not([data-mounted="1"])'));

  mounts.forEach(mount => {
    const source = mount.previousElementSibling;
    const status = parseStatusSource(source instanceof HTMLElement ? source : null);
    mount.dataset.mounted = '1';
    createApp(App, { status }).mount(mount);
  });
}

mountStatusBars();
