import type { NpcStatus, StatusData } from './types';

function normalizeText(value: string | undefined) {
  return (value ?? '').replace(/\r/g, '').trim();
}

function parseNpcBlock(raw: string) {
  const text = normalizeText(raw);
  if (!text || text === '无') {
    return [] as NpcStatus[];
  }

  const result: NpcStatus[] = [];
  const pattern = /👤\s*(.+?)（(.+?)，(.+?)）\s*\n\s*💭\s*心理：([\s\S]*?)(?=\n\s*👤|\s*$)/g;

  for (const match of text.matchAll(pattern)) {
    result.push({
      name: normalizeText(match[1]),
      age: normalizeText(match[2]),
      role: normalizeText(match[3]),
      mindset: normalizeText(match[4]),
    });
  }

  return result;
}

export function parseStatusSource(source: HTMLElement | null) {
  if (!source) {
    return null;
  }

  const data: StatusData = {
    title: normalizeText(source.dataset.title) || '天元界·实时状态',
    time: normalizeText(source.dataset.time) || '未知',
    location: normalizeText(source.dataset.location) || '未知',
    weather: normalizeText(source.dataset.weather) || '未知',
    npcs: parseNpcBlock(source.textContent ?? ''),
  };

  return data;
}
